styleText:
/* ─── Reset & Base ─── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --card:       #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full: 9999px;
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.4;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }
    a { text-decoration: none; color: inherit; }

    /* ─── Animations ─── */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeIn {
      from { opacity: 0; }
      to   { opacity: 1; }
    }
    @keyframes float {
      0%, 100% { transform: translateY(0px); }
      50%       { transform: translateY(-8px); }
    }
    @keyframes marquee {
      0%   { transform: translate3d(0, 0, 0); }
      100% { transform: translate3d(-25%, 0, 0); }
    }
    @keyframes pulse-dot {
      0%, 100% { opacity: 1; transform: scale(1); }
      50%       { opacity: 0.5; transform: scale(0.85); }
    }
.fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .delay-1    { animation-delay: 0.1s; }
    .delay-2    { animation-delay: 0.2s; }
    .delay-3    { animation-delay: 0.3s; }
    .delay-4    { animation-delay: 0.4s; }
    .delay-5    { animation-delay: 0.5s; }
    .delay-6    { animation-delay: 0.6s; }

    /* ─── Utility ─── */
    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 32px;
    }
    .section { padding: 100px 0; }
    .section-sm { padding: 64px 0; }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--muted);
      margin-bottom: 18px;
    }
    .eyebrow-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: var(--accent);
      animation: pulse-dot 2s ease infinite;
    }
    .section-headline {
      font-size: clamp(30px, 4vw, 46px);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.025em;
      color: var(--text);
      margin-bottom: 14px;
    }
    .section-sub {
      font-size: 16px;
      color: var(--muted);
      max-width: 480px;
      line-height: 1.7;
    }
    .accent-text { color: #8A6B40; }

    /* ─── Buttons ─── */
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      border-radius: var(--radius-full);
      font-family: 'Inter', sans-serif;
      font-weight: 600;
      font-size: 14px;
      cursor: pointer;
      transition: all 0.2s cubic-bezier(.22,1,.36,1);
      border: none;
      outline: none;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--dark);
      color: #fff;
      padding: 13px 28px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    }
    .btn-primary:hover {
      background: var(--dark-2);
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    }
    .btn-accent {
      background: var(--accent);
      color: var(--dark);
      padding: 13px 28px;
      box-shadow: 0 2px 8px rgba(205,177,139,0.3);
    }
    .btn-accent:hover {
      background: #dac09e;
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(205,177,139,0.4);
    }
    .btn-outline {
      background: transparent;
      color: var(--text);
      padding: 12px 24px;
      border: 1.5px solid var(--border-2);
    }
    .btn-outline:hover {
      background: var(--white);
      color: #0D1117 !important;
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }
    .btn-ghost {
      background: transparent;
      color: var(--muted);
      padding: 12px 20px;
      font-weight: 500;
    }
    .btn-ghost:hover { color: var(--text); }
    .btn-icon {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: var(--dark);
      color: #fff;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
    }
    .btn-icon:hover { background: #1d2535; transform: scale(1.05); }

    /* ─── NAVBAR ─── */
    .navbar {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      padding: 0 40px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      background: rgba(247,247,244,0.82);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
    }
    .nav-logo {
      display: flex;
      align-items: center;
      gap: 9px;
      font-weight: 800;
      font-size: 18px;
      letter-spacing: -0.03em;
    }
    .nav-logo-icon {
      width: 30px; height: 30px;
      background: var(--dark);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .nav-logo-icon svg { width: 16px; height: 16px; }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 2px;
      list-style: none;
    }
    .nav-links a {
      font-size: 13px;
      font-weight: 500;
      color: var(--muted);
      padding: 7px 11px;
      border-radius: var(--radius-full);
      transition: all 0.15s;
      display: flex;
      align-items: center;
      gap: 3px;
      white-space: nowrap;
    }
    .nav-links a:hover { color: var(--text); background: rgba(0,0,0,0.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display: flex; align-items: center; gap: 10px; }

    /* ─── Mega Menu ─── */
    .nav-item { position: relative; list-style: none; }
    .nav-chevron {
      font-size: 9px;
      opacity: 0.45;
      transition: transform 0.18s;
      line-height: 1;
    }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform: rotate(180deg); opacity: 0.7; }

    .mega-panel {
      position: fixed;
      top: 64px;
      left: 50%;
      transform: translateX(-50%) translateY(-6px);
      background: var(--white);
      border: 1px solid var(--border-2);
      border-radius: var(--radius-lg);
      box-shadow: 0 8px 16px rgba(0,0,0,0.06), 0 24px 64px rgba(0,0,0,0.10);
      padding: 24px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.18s ease, transform 0.18s ease;
      z-index: 999;
    }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-products  { width: 1040px; }
    .mega-solutions { width: 680px; }
    .mega-platform  { width: 680px; }

    /* Thin top accent bar */
    .mega-panel::before {
      content: '';
      position: absolute;
      top: 0; left: 24px; right: 24px;
      height: 2px;
      background: var(--accent);
      border-radius: 0 0 2px 2px;
      opacity: 0.6;
    }
    /* Transparent hover bridge — prevents gap closing the menu */
    .mega-panel::after {
      content: '';
      position: absolute;
      top: -18px; left: 0; right: 0;
      height: 18px;
    }

    /* Hightouch-style column mega */
    .mega-cols { display:flex; align-items:flex-start; gap:0; }
    .mega-col {
      flex:1; padding:0 28px;
      border-right:1px solid var(--border-2);
      min-width:0;
    }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }

    .mega-col-label {
      font-size:10px; font-weight:700; letter-spacing:.1em;
      text-transform:uppercase; color:var(--muted);
      margin-bottom:16px; padding-bottom:12px;
      border-bottom:1px solid var(--border-2);
      white-space:nowrap;
    }
    .mega-col-link {
      display:block; font-size:14px; color:var(--text);
      text-decoration:none; padding:7px 0; font-weight:500;
      transition:color .15s; white-space:nowrap;
    }
    .mega-col-link:hover { color:var(--accent); }

    .mega-col-badge {
      font-size:9px; font-weight:700; letter-spacing:.05em;
      text-transform:uppercase; color:var(--accent);
      background:rgba(205,177,139,.15); border-radius:3px;
      padding:2px 5px; margin-left:6px; vertical-align:middle;
    }

    /* Featured column */
    .mega-col-featured { flex:0 0 200px !important; padding:0 0 0 28px !important; border-right:none !important; }
    .mega-featured-img {
      width:100%; height:110px; border-radius:var(--radius-sm);
      overflow:hidden; margin-bottom:12px;
    }
    .mega-featured-img img { width:100%; height:100%; object-fit:cover; }
    .mega-featured-desc {
      font-size:12.5px; color:var(--muted); line-height:1.65; margin-bottom:12px;
    }
    .mega-featured-link {
      font-size:12.5px; font-weight:600; color:var(--text);
      text-decoration:none; display:flex; align-items:center; gap:4px;
    }
    .mega-featured-link:hover { color:var(--accent); }

    /* ─── HERO ─── */
    .hero {
      padding-top: 0;
      padding-bottom: 0;
      position: relative;
      overflow: hidden;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }
    /* Full-bleed landscape */
    .hero-landscape {
      position: absolute;
      inset: 0;
      z-index: 0;
      overflow: hidden;
    }
    .hero-landscape svg {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    /* White fade at bottom */
    .hero-landscape-fade {
      position: absolute;
      inset: 0;
      background: linear-gradient(
        to bottom,
        rgba(247,247,244,0) 0%,
        rgba(247,247,244,0.1) 40%,
        rgba(247,247,244,0.7) 72%,
        rgba(247,247,244,1) 88%
      );
      pointer-events: none;
    }
    /* Dark overlay on top half for text legibility */
    .hero-landscape-top {
      position: absolute;
      inset: 0;
      background: linear-gradient(
        to bottom,
        rgba(10,12,18,0.55) 0%,
        rgba(10,12,18,0.25) 55%,
        transparent 75%
      );
      pointer-events: none;
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      pointer-events: none;
    }
    .hero-bg-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.35;
    }
    .hero-bg-blob-1 {
      width: 600px; height: 600px;
      background: radial-gradient(circle, #CDB18B 0%, transparent 70%);
      top: -200px; right: -100px;
    }
    .hero-bg-blob-2 {
      width: 400px; height: 400px;
      background: radial-gradient(circle, #D0F0FF 0%, transparent 70%);
      bottom: 0; left: -100px;
    }
    .hero-inner {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      position: relative;
      z-index: 1;
      padding-top: 200px;
      padding-bottom: 48px;
      flex: 1;
    }
    .hero-content { max-width: 540px; }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      border: 1px solid var(--border-2);
      border-radius: var(--radius-full);
      padding: 5px 14px 5px 6px;
      font-size: 12px;
      font-weight: 500;
      color: var(--muted);
      margin-bottom: 28px;
      box-shadow: var(--shadow-xs);
    }
    .hero-badge-pill {
      background: var(--accent);
      color: var(--dark);
      border-radius: var(--radius-full);
      padding: 3px 10px;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.04em;
    }
    .hero-headline {
      font-size: clamp(32px, 4.5vw, 56px);
      font-weight: 900;
      line-height: 1.04;
      letter-spacing: -0.04em;
      margin-bottom: 22px;
      color: var(--text);
    }
    .hero-headline em {
      font-style: italic;
      font-family: 'DM Serif Display', serif;
      font-weight: 400;
    } h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .hero-sub { font-size:17px; color:var(--text); line-height:1.7; max-width:600px; margin-bottom:36px; }
    .hero-ctas {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 44px;
      flex-wrap: wrap;
    }
    .hero-social-proof {
      display: flex;
      align-items: center;
      gap: 14px;
    }
    .avatar-stack {
      display: flex;
      align-items: center;
    }
    .avatar {
      width: 32px; height: 32px;
      border-radius: 50%;
      border: 2.5px solid var(--bg);
      background: var(--dark);
      margin-left: -8px;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      font-weight: 700;
      color: #fff;
    }
    .avatar:first-child { margin-left: 0; }
    .avatar-1 { background: #6366F1; }
    .avatar-2 { background: #F59E0B; }
    .avatar-3 { background: #10B981; }
    .avatar-4 { background: #EF4444; }
    .avatar-5 { background: #8B5CF6; }
    .proof-text { font-size: 13px; color: var(--muted); font-weight: 500; }
    .proof-text strong { color: var(--text); }
    .stars { color: #F59E0B; font-size: 13px; margin-right: 2px; }

    /* Hero Dashboard Card */
    .hero-visual {
      position: relative;
      animation: float 6s ease-in-out infinite;
    }
    .dashboard-card {
      background: var(--white);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-xl);
      border: 1px solid var(--border);
      overflow: hidden;
      position: relative;
    }
    .dash-header {
      padding: 16px 20px;
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: space-between;
      background: var(--white);
    }
    .dash-dots { display: flex; gap: 6px; }
    .dash-dot {
      width: 10px; height: 10px;
      border-radius: 50%;
      background: #E5E7EB;
    }
    .dash-dot-red   { background: #FCA5A5; }
    .dash-dot-yel   { background: var(--accent); }
    .dash-dot-grn   { background: #86EFAC; }
    .dash-title { font-size: 12px; font-weight: 600; color: var(--muted); }
    .dash-status {
      display: flex;
      align-items: center;
      gap: 5px;
      font-size: 11px;
      font-weight: 600;
      color: #16A34A;
    }
    .dash-status-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: #16A34A;
      animation: pulse-dot 1.5s ease infinite;
    }
    .dash-body {
      display: grid;
      grid-template-columns: 160px 1fr;
      min-height: 340px;
    }
    .dash-sidebar {
      border-right: 1px solid var(--border);
      padding: 16px 12px;
      display: flex;
      flex-direction: column;
      gap: 4px;
      background: #FAFAFA;
    }
    .dash-nav-item {
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 8px 10px;
      border-radius: var(--radius-sm);
      font-size: 12px;
      font-weight: 500;
      color: var(--muted);
      cursor: default;
    }
    .dash-nav-item.active {
      background: var(--dark);
      color: #fff;
    }
    .dash-nav-item.active .dash-nav-icon { background: var(--accent); color: var(--dark); }
    .dash-nav-icon {
      width: 22px; height: 22px;
      border-radius: 6px;
      background: var(--border);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
    }
    .dash-main { padding: 16px; display: flex; flex-direction: column; gap: 12px; }
    .dash-kpi-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
    }
    .dash-kpi {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 12px;
    }
    .dash-kpi-label { font-size: 10px; color: var(--muted); font-weight: 500; margin-bottom: 5px; }
    .dash-kpi-val { font-size: 20px; font-weight: 800; letter-spacing: -0.03em; }
    .dash-kpi-change { font-size: 10px; color: #16A34A; font-weight: 600; margin-top: 2px; }
    .dash-chart {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 14px;
      flex: 1;
    }
    .dash-chart-label { font-size: 11px; font-weight: 600; color: var(--muted); margin-bottom: 10px; }
    .chart-bars {
      display: flex;
      align-items: flex-end;
      gap: 5px;
      height: 80px;
    }
    .chart-bar {
      flex: 1;
      border-radius: 4px 4px 0 0;
      background: var(--border-2);
      min-height: 10px;
      transition: all 0.3s;
    }
    .chart-bar.accent { background: var(--dark); }
    .chart-bar.active { background: var(--accent); }
    .dash-tasks {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 12px;
    }
    .dash-task-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 5px 0;
      font-size: 11px;
      border-bottom: 1px solid var(--border);
    }
    .dash-task-row:last-child { border-bottom: none; }
    .dash-task-check {
      width: 14px; height: 14px;
      border-radius: 4px;
      border: 1.5px solid var(--border-2);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 9px;
    }
    .dash-task-check.done { background: var(--dark); border-color: var(--dark); color: #fff; }
    .dash-task-text { flex: 1; color: var(--text); }
    .dash-task-tag {
      background: var(--accent-dim);
      color: #8A6B40;
      font-size: 9px;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: var(--radius-full);
    }
    .dash-task-tag.purple { background: #EDE9FE; color: #7C3AED; }
    .dash-task-tag.blue   { background: #DBEAFE; color: #1D4ED8; }

    /* Floating mini cards */
    .hero-float-card {
      position: absolute;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--border);
      padding: 12px 16px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 12px;
      font-weight: 500;
      white-space: nowrap;
    }
    .float-card-icon {
      width: 32px; height: 32px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      flex-shrink: 0;
    }
    .float-card-1 { bottom: -20px; left: -40px; }
    .float-card-2 { top: 40px; right: -50px; }

    /* ─── LOGOS STRIP ─── */
    .logos-section {
      padding: 48px 0;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      background: var(--white);
      overflow: hidden;
    }
    .logos-label {
      text-align: center;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--muted-2);
      margin-bottom: 28px;
    }
    .logos-track-wrap { overflow: hidden; position: relative; }
    .logos-track-wrap::before,
    .logos-track-wrap::after {
      content: '';
      position: absolute;
      top: 0; bottom: 0;
      width: 120px;
      z-index: 2;
      pointer-events: none;
    }
    .logos-track-wrap::before { left: 0; background: linear-gradient(to right, #fff, transparent); }
    .logos-track-wrap::after  { right: 0; background: linear-gradient(to left, #fff, transparent); }
    .logos-track {
      display: flex;
      align-items: center;
      gap: 64px;
      animation: marquee 28s linear infinite;
      width: max-content;
      will-change: transform;
      backface-visibility: hidden;
    }
    .logo-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 15px;
      font-weight: 700;
      color: #9CA3AF;
      letter-spacing: -0.02em;
      user-select: none;
      transition: color 0.2s;
    }
