    .testi-v2-card { background:var(--white);border:1px solid var(--border-2);border-radius:20px;padding:28px;box-shadow:0 2px 12px rgba(0,0,0,.05);transition:transform .2s,box-shadow .2s;cursor:default; }
    .testi-v2-card:hover { transform:translateY(-4px) scale(1.02);box-shadow:0 16px 48px rgba(0,0,0,.1); }
    .testi-v2-quote { font-size:14px;line-height:1.75;color:var(--muted);margin-bottom:20px; }
    .testi-v2-author { display:flex;align-items:center;gap:12px; }
