#wc-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
}
#wc-canvas {
  display: block;
  width: 100%;
  height: 100%;
  /* SVG turbulence filter = ink soaking into paper fibers */
  filter: url(#wc-ink);
}
/* Delay hero elements so they appear through the spreading ink */
body.wc-active .hero-headline.fade-in-up { animation-delay: 0.6s !important; }
body.wc-active .hero-sub.fade-in-up      { animation-delay: 1.0s !important; }
body.wc-active .hero-ctas.fade-in-up     { animation-delay: 1.4s !important; }

    .product-section { padding-top: 0; padding-bottom: 0; }
