    /* ── Product Section Mobile Sticky Stack ── */
    @media (max-width: 768px) {
      /* 1. Kill the desktop 5×100vh scroll system */
      #product { height: auto !important; padding: 60px 0 40px !important; }
      .product-inner {
        position: static !important;
        height: auto !important;
        overflow: visible !important;
        padding: 0 !important;
        justify-content: flex-start !important;
      }
      /* 2. Single column, no gap, hide right image */
      .product-cols { display: block !important; }
      .product-visual { display: none !important; }
      /* 3. Stacking container — overflow:visible is critical for sticky */
      .product-tabs-wrap { overflow: visible !important; }
      .product-tabs {
        display: block !important;
        overflow: visible !important;
        /* enough bottom padding so last card can fully un-stick */
        padding-bottom: 0 !important;
      }
      /* 4. Base card: sticky, solid white, rounded, shadowed */
      .product-tab {
        position: sticky !important;
        top: 80px !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: flex-start !important;
        gap: 12px !important;
        padding: 22px 20px !important;
