        border: 1px solid var(--border) !important;
        border-radius: 20px !important;
        box-shadow: 0 2px 16px rgba(0,0,0,0.07) !important;
        /* small margin so next card is just below — creates the overlap on scroll */
        margin-bottom: 16px !important;
        transform-origin: top center !important;
        transition: transform 0.35s cubic-bezier(0.22,1,0.36,1), box-shadow 0.3s !important;
        will-change: transform !important;
      }
      /* 5. Stagger top + z-index: later cards sit higher and stack on top */
      .product-tab:nth-child(1) { z-index: 1 !important; }
      .product-tab:nth-child(2) { z-index: 2 !important; }
      .product-tab:nth-child(3) { z-index: 3 !important; }
      .product-tab:nth-child(4) { z-index: 4 !important; }
      .product-tab:nth-child(5) { z-index: 5 !important; }
      /* 7. Active card: full size, accent border, elevated */
      .product-tab.active {
        border-color: rgba(205,177,139,0.5) !important;
        box-shadow: 0 6px 28px rgba(0,0,0,0.10) !important;
      }
