      .product-tab-icon { width: 44px !important; height: 44px !important; border-radius: 12px !important; flex-shrink: 0 !important; }
      .product-tab-body { width: 100% !important; }
      .product-tab-title { font-size: 15px !important; font-weight: 700 !important; margin-bottom: 5px !important; }
      .product-tab-desc { font-size: 13px !important; line-height: 1.65 !important; color: var(--muted) !important; }
