(function() {
    document.querySelectorAll('.nav-item.has-mega').forEach(function(item) {
      var panel = item.querySelector('.mega-panel');
      var timer;
      function openMenu()  { clearTimeout(timer); item.classList.add('mega-open'); }
      function closeMenu() { timer = setTimeout(function() { item.classList.remove('mega-open'); }, 120); }
      item.addEventListener('mouseenter', openMenu);
      item.addEventListener('mouseleave', closeMenu);
      if (panel) {
        panel.addEventListener('mouseenter', openMenu);
        panel.addEventListener('mouseleave', closeMenu);
      }
    });
  })();

// Animate bars on scroll
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('fade-in-up');
      }
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('.bento-card, .testi-card, .pricing-card, .integration-card').forEach(el => {
    observer.observe(el);
  });

  // Product tab switching
  document.querySelectorAll('.product-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.product-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
    });
  });

  // Pricing toggle (visual only)
  const toggleTrack = document.querySelector('.toggle-track');
  const toggleThumb = document.querySelector('.toggle-thumb');
  let annual = true;
  if (toggleTrack) {
    toggleTrack.addEventListener('click', () => {
      annual = !annual;
      toggleThumb.style.transform = annual ? 'translateX(0)' : 'translateX(-18px)';
    });
  }

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) { item.classList.add('open'); icon.textContent = '−'; }
  }

(function() {
  var activeIndex = 0;
  var PEEK_STEP = 20;   // px each past card peeks from top
  var MAX_PEEK  = 3;    // max 3 cards peeking

  function updateStack(idx) {
    var stack  = document.querySelector('.product-img-stack');
    var cards  = Array.from(document.querySelectorAll('.product-img-card'));
    if (!stack) return;

    var H          = stack.offsetHeight;
    var peekTotal  = PEEK_STEP * Math.min(idx, MAX_PEEK); // total top space reserved

    cards.forEach(function(card, i) {
      var diff = i - idx;

      if (diff === 0) {
        // ── Active card: slides up from bottom into peeked position ──
        card.style.zIndex     = 20;
        card.style.transform  = 'translateY(' + peekTotal + 'px)';
        card.style.opacity    = '1';
        card.style.boxShadow  = '0 -6px 28px rgba(0,0,0,0.22)';

      } else if (diff < 0) {
        // ── Past cards: peek from the top ──
        var absDiff  = Math.abs(diff);
        var peekPos  = peekTotal - absDiff * PEEK_STEP; // top position in px
        var scale    = 1 - absDiff * 0.015;
        card.style.zIndex     = 20 - absDiff;
        card.style.transform  = 'translateY(' + Math.max(peekPos, 0) + 'px) scale(' + scale + ')';
        card.style.opacity    = absDiff > MAX_PEEK ? '0' : '1';
        card.style.boxShadow  = '0 -2px 10px rgba(0,0,0,0.10)';

      } else {
        // ── Future cards: wait below, slide up when active ──
        card.style.zIndex     = 1;
        card.style.transform  = 'translateY(' + H + 'px)';
        card.style.opacity    = '0';
        card.style.boxShadow  = 'none';
      }
    });

    activeIndex = idx;
  }

  function switchTab(el) {
    document.querySelectorAll('.product-tab').forEach(function(t) { t.classList.remove('active'); });
    el.classList.add('active');
    var idx = parseInt(el.getAttribute('data-index') || '0');
    updateStack(idx);
  }
  window.switchTab = switchTab;

  // Assign data-index to tabs
  var tabs = Array.from(document.querySelectorAll('.product-tab[data-image]'));
  tabs.forEach(function(tab, i) { tab.setAttribute('data-index', i); });

  var section = document.getElementById('product');
  if (!section || !tabs.length) return;

  // Initial state
  updateStack(0);
  if (tabs[0]) tabs[0].classList.add('active');

  // Scroll-progress switching
  var ticking = false;
  window.addEventListener('scroll', function() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function() {
      var rect      = section.getBoundingClientRect();
      var scrolledIn = -rect.top;
      var scrollRange = section.offsetHeight - window.innerHeight;
      var progress  = Math.max(0, Math.min(1, scrolledIn / scrollRange));
      var idx       = Math.min(tabs.length - 1, Math.floor(progress * tabs.length));

      if (idx !== activeIndex && tabs[idx]) switchTab(tabs[idx]);

      // Also re-run updateStack on resize to recalculate H
      ticking = false;
    });
  }, { passive: true });

  window.addEventListener('resize', function() { updateStack(activeIndex); });
})();
